"""Original, deterministic problem families; exact arithmetic and independent checks."""
from fractions import Fraction as F
from math import comb, factorial, gcd, lcm, isqrt, floor, ceil
from itertools import product, combinations, permutations
import random

def tex(x):
 x=F(x)
 if x.denominator==1:return str(x.numerator)
 sign='-' if x<0 else ''
 return sign+r'\frac{'+str(abs(x.numerator))+'}{'+str(x.denominator)+'}'
def M(x):return '$'+tex(x)+'$'
def blocks(value):
 parts=[]; current=''; in_math=False
 for char in value:
  if char=='$':in_math=not in_math
  if char=='|' and not in_math:
   parts.append(current);current=''
  else:current+=char
 parts.append(current)
 return parts
def Q(stem,answer,work,hint,bad=None,check=None):
 answer=F(answer)
 if check is not None:
  assert answer==F(check),f'{stem}: {answer} != {check}'
 wrong=[]
 for v in (bad or [])+[answer+1,answer-1,answer*2,answer/2,answer+2,answer+3,answer-2,answer+4]:
  v=F(v)
  if v!=answer and v not in wrong:wrong.append(v)
  if len(wrong)==4:break
 assert len(wrong)==4
 return dict(stem=stem,answer=tex(answer),exact=str(answer),wrong=[tex(x) for x in wrong],solution=blocks(work),hints=blocks(hint),checked=check is not None)

def fractions(t):
 a,b=t+2,t+3
 return [
 Q(f'What is ${a}/{b}+1/{2*b}$?',F(2*a+1,2*b),f'Use denominator ${2*b}$.|The numerator is ${2*a}+1$, so the sum is {M(F(2*a+1,2*b))}.','Use pieces of the same size.|Double both parts of the first fraction.',[F(a+1,3*b),F(a+1,2*b),F(a,b)],check=F(a,b)+F(1,2*b)),
 Q(f'What is the value of ${a}+\\frac{{1}}{{{a}+1/{a}}}$?',a+F(a,a*a+1),f'Inside, ${a}+1/{a}=({a*a+1})/{a}$.|Invert this inner fraction and add ${a}$ to get {M(a+F(a,a*a+1))}.','Start with the innermost denominator.|The reciprocal of a/b is b/a.',[a+F(1,a),a+F(1,a*a),a+F(1,2*a)],check=F(a)+1/(F(a)+F(1,a))),
 Q(f'A tank is $1/{a}$ full. Adding ${b}$ liters makes it $1/2$ full. What is its capacity in liters?',F(2*a*b,a-2),f'The added fraction is $1/2-1/{a}=({a-2})/{2*a}$.|Divide the added liters by this fraction: {M(F(2*a*b,a-2))}.','Find the fraction of the tank that was added.|Capacity times the added fraction equals the added liters.',[2*b,a*b,F(b,a-2)],check=F(b)/(F(1,2)-F(1,a))),
 Q(f'What is $\\frac{{1/{a}+1/{b}}}{{1/{a}-1/{b}}}$?',F(a+b,b-a),f'Multiply numerator and denominator by ${a*b}$.|The expression becomes $({b}+{a})/({b}-{a})={a+b}$.','Clear both small denominators at once.|Multiply the entire numerator and denominator by their product.',[F(b-a,a+b),a*b,a+b-1],check=(F(1,a)+F(1,b))/(F(1,a)-F(1,b))),
 Q(f'A number multiplied by ${a}/{b}$ and then increased by $1/{b}$ becomes ${a+1}$. What is the number?',F((a+1)*b-1,a),f'Write $({a}/{b})x+1/{b}={a+1}$.|Multiplying by ${b}$ and isolating x gives {M(F((a+1)*b-1,a))}.','Undo the addition before the multiplication.|Multiply the entire equation by the denominator.',[a+1,b,a+b],check=(F(a+1)-F(1,b))*F(b,a)),
 Q(f'For positive $x$, $\\frac1x+\\frac1{{{a}x}}=\\frac1{{{b}}}$. What is $x$?',F(b*(a+1),a),f'Combine the left side as $({a+1})/({a}x)$.|Cross-multiplication gives $x={tex(F(b*(a+1),a))}$.','Factor out 1/x.|Clear denominators only after combining the two terms.',[a*b,a+b,F(b,a+1)],check=F(b)*(1+F(1,a))),
 Q(f'A student spends $1/{a}$ of her money, then $1/{b}$ of what remains. What fraction of the original money is left?',F((a-1)*(b-1),a*b),f'The remaining factors are $({a-1})/{a}$ and $({b-1})/{b}$.|Multiply them to obtain {M(F((a-1)*(b-1),a*b))}.','The second fraction has a new whole.|Track the fraction left after each purchase.',[1-F(1,a)-F(1,b),F(1,a*b),F(a+b-2,a*b)],check=(1-F(1,a))*(1-F(1,b))) ]

def ratios(t):
 a,b=t+2,t+3;p=10*t; total=(a+b)*12
 return [
 Q(f'Red and blue beads are in ratio ${a}:{b}$. There are ${total}$ beads. How many are red?',12*a,f'There are ${a+b}$ equal ratio parts.|Each is 12 beads, so red contributes ${12*a}$.','Count all ratio parts.|Divide the total by the sum of the ratio numbers.',[12*b,total-a,12],check=F(total*a,a+b)),
 Q(f'A price of $200$ dollars rises by ${p}\\%$ and then falls by ${p}\\%$. What is the final price?',200*(1-F(p*p,10000)),f'Multiply by $1+{p}/100$ and $1-{p}/100$.|The final price is {M(200*(1-F(p*p,10000)))} dollars.','Use multiplicative factors.|The decrease applies to the increased price.',[200,200+2*p,200-2*p],check=200*(1+F(p,100))*(1-F(p,100))),
 Q(f'After a ${p}\\%$ discount, an item costs ${2*(100-p)}$ dollars. What was its original price?',200,f'The final price is ${100-p}/100$ of the original.|Divide ${2*(100-p)}$ by this factor to obtain $200$.','Reverse the multiplier.|Original price times (1-discount) equals final price.',[2*(100-p)*(1+F(p,100)),2*(100-p)-p,2*(100-p)+p],check=F(2*(100-p),1-F(p,100))),
 Q(f'A mixture contains ${a}$ liters at $20\\%$ concentration and ${b}$ liters at $60\\%$. What is the final concentration, as a percentage?',F(20*a+60*b,a+b),f'The ingredient amount is $0.2({a})+0.6({b})$ liters.|Divide by ${a+b}$ total liters and multiply by 100: {M(F(20*a+60*b,a+b))} percent.','Add ingredient amounts, not percentages.|Weight each concentration by its volume.',[40,80,F(20*b+60*a,a+b)],check=100*(F(a,5)+F(3*b,5))/(a+b)),
 Q(f'The ratio of $A$ to $B$ is $2:3$, and $B:C=4:{a}$. What is $A/C$?',F(8,3*a),f'Match the B parts: $A:B:C=8:12:{3*a}$.|Therefore $A/C={tex(F(8,3*a))}$.','Give B the same scale in both ratios.|Multiply the first ratio by four and the second by three.',[F(2,a),F(3,a),F(8,a)],check=F(2,3)*F(4,a)),
 Q(f'A rectangle is scaled with length scale ${a}/{b}$. Its new area is ${a*a*9}$. What was its old area?',b*b*9,f'Area scales by $({a}/{b})^2$.|Divide the new area by this factor to get ${b*b*9}$.','Two dimensions change.|Use the square of the length scale.',[a*b*9,a*a*9,b*b*3],check=F(a*a*9)*F(b,a)**2),
 Q(f'A class has ${a}$ girls for every ${b}$ boys. After $12$ girls join, the ratio becomes ${a+1}:{b}$. How many students were there originally?',12*(a+b),f'Write the original counts as ${a}k,{b}k$.|The new ratio forces ${a}k+12=({a+1})k$, so $k=12$.|The original total is ${12*(a+b)}$.','Use one scale factor for both original groups.|The number of boys is unchanged.',[12*a,12*b,12*(a+b+1)],check=sum([a*12,b*12])) ]

def rates(t):
 a=t+2;b=a+2;d=12*a*b
