 Q(f'If $x=-{a}$, what is $\\sqrt{{(x-1)^2}}$?',a+1,f'The square root is $|x-1|$.|At $x=-{a}$, this is ${a+1}$.','The square root is nonnegative.|Use absolute value after taking the square root of a square.',[-a-1,a-1,a*a-1],check=isqrt((-a-1)**2)),
 Q(f'If $3^x={3**(t+1)}$, what is $9^{{x+1}}$?',3**(2*t+4),f'The exponent x is ${t+1}$.|Then $9^{{x+1}}=3^{{2(x+1)}}={3**(2*t+4)}$.','Rewrite both sides with base 3.|The exponent doubles when base 9 becomes base 3.',[3**(t+2),3**(2*t+2),9**t],check=9**(t+2)),
 Q(f'For $a={t+3}$, simplify $\\sqrt{{{(t+3)**2*7}}}/\\sqrt7$.',t+3,f'The radicand is $7({t+3})^2$.|Cancel the common positive radical to obtain ${t+3}$.','Factor out a perfect square.|Both square roots have positive radicands.',[(t+3)**2,7*(t+3),F(t+3,7)],check=isqrt(((t+3)**2*7)//7)),
 Q(f'What is $(\\sqrt{{{a+1}}}+\\sqrt{{{a}}})(\\sqrt{{{a+1}}}-\\sqrt{{{a}}})$?',1,f'Use difference of squares.|The result is ${a+1}-{a}=1$.','The factors are conjugates.|The mixed radical terms cancel.',[2*a+1,a,2],check=(a+1)-a),
 Q(f'How many integers $k$ satisfy ${a*a}<k^2<{(a+3)**2}$?',4,f'The positive possibilities are ${a+1}$ and ${a+2}$.|Their negatives also work, giving four integers.','Locate the square between consecutive square bounds.|Include negative integers and respect strict inequalities.',[2,3,6],check=sum(a*a<k*k<(a+3)**2 for k in range(-a-4,a+5))),
