 Q(f'If r,s are roots of $x^2-{s}x+{p}=0$, what is $(r+2)(s+2)$?',p+2*s+4,f'Expand only the shifted product: $rs+2(r+s)+4$.|It equals ${p+2*s+4}$.','Use symmetric quantities after expanding.|You do not need the individual roots.',[p+4,p+2*s,p+2],check=(a+2)*(b+2)),
 Q(f'If r,s are roots of $x^2-{s}x+{p}=0$, what is $r/s+s/r$?',F(s*s-2*p,p),f'Combine as $(r^2+s^2)/(rs)$.|Substitute the symmetric expressions to obtain {M(F(s*s-2*p,p))}.','Put the fractions over denominator rs.|Compute the numerator from the root sum.',[F(s*s,p),F(s,p),F(p,s*s)],check=F(a,b)+F(b,a)),
